// Upgrade prices and durations, from upgrade-costs.json (GENERATED by
// scripts/game-data.ts — see README.md).
//
// Its own module rather than part of index.ts, because index.ts runs in the
// browser for the paste view and this table is 66 KB. Only server code imports
// it (services/upgrades.ts, the tracker's Server Actions); what reaches the
// browser is the handful of prices a page actually shows.
//
// ONE RULE FOR EVERY ROW: levels[L - 1] is the price of REACHING level L. The
// two sources disagree about this — coc.py prices buildings that way and units
// as the cost of LEAVING a level — and the generator, not every caller, is
// where that difference is settled.

import costsFile from "./upgrade-costs.json";
import type { Village } from "@/types/domain";

/** Every resource an upgrade can cost. The three ores are equipment's. */
export type Resource =
  | "gold"
  | "elixir"
  | "dark"
  | "builderGold"
  | "builderElixir"
  | "gems"
  | "shiny"
  | "glowy"
  | "starry";

export interface Price {
  resource: Resource;
  amount: number;
}

export type SubjectType = "building" | "unit" | "weapon";

export interface UpgradeStep {
  /** The level this step reaches. */
  level: number;
  /** What it costs; several entries only for equipment's ores. */
  cost: Price[];
  /** Walls from level 5: the same amount, payable in this instead. */
  alt?: Price;
  seconds: number;
}

type FileResource = Exclude<Resource, "shiny" | "glowy" | "starry"> | "ore";

interface CostRow {
  type: SubjectType;
  name: string;
  village: Village;
  resource: FileResource;
  alt?: FileResource;
  altFrom?: number;
  hall?: number;
  levels: Array<[number | number[], number] | null>;
}

const ROWS = costsFile.costs as CostRow[];
const ORES: Resource[] = ["shiny", "glowy", "starry"];

const key = (type: SubjectType, name: string, village: Village) => `${type}:${village}:${name}`;
const byKey = new Map(ROWS.map((r) => [key(r.type, r.name, r.village), r]));

/**
 * The price of reaching `toLevel`, or null when no source has it — a unit's
 * level 1 (a building unlocks it), a level newer than the data, or a subject
 * the data has never heard of. Callers show the step without a price; they
 * never guess one.
 */
export function upgradeStep(
  type: SubjectType,
  name: string,
  village: Village,
  toLevel: number,
): UpgradeStep | null {
  const row = byKey.get(key(type, name, village));
  const entry = row?.levels[toLevel - 1];
  if (!row || !entry) return null;

  const [amount, seconds] = entry;
  const cost: Price[] = Array.isArray(amount)
    ? amount.flatMap((n, i) => (n > 0 ? [{ resource: ORES[i]!, amount: n }] : []))
    : [{ resource: row.resource as Resource, amount }];

  const step: UpgradeStep = { level: toLevel, cost, seconds };
  if (row.alt && row.altFrom !== undefined && toLevel >= row.altFrom && !Array.isArray(amount)) {
    step.alt = { resource: row.alt as Resource, amount };
  }
  return step;
}

/** The Town Hall weapon's name at a hall, e.g. "Inferno Artillery" at TH17. */
export function weaponAt(hall: number | null | undefined): string | null {
  return ROWS.find((r) => r.type === "weapon" && r.hall === hall)?.name ?? null;
}
